from core.rules import RuleMachine


class SafeSortedDestinationRule:
    """Permite movimientos hacia destinos plausibles y los ordena por preferencia:
    primero vacíos, luego pilas con tope bajo, y da una leve ventaja a destinos ya ordenados."""

    name = "safe_sorted_destination_rule"

    def __init__(self, prefer_empty=True, empty_bonus=-1.5, top_weight=1.0, sorted_bonus=-0.5, same_group_bonus=-0.25):
        self.prefer_empty = prefer_empty
        self.empty_bonus = empty_bonus
        self.top_weight = top_weight
        self.sorted_bonus = sorted_bonus
        self.same_group_bonus = same_group_bonus

    def _score(self, partial, a):
        sd = a.sd
        so = a.so
        dest_h = partial.h(sd)
        src_top = partial.g(so)
        dest_top = partial.g(sd)

        score = float(dest_top) * self.top_weight

        if dest_h == 0:
            if self.prefer_empty:
                score += self.empty_bonus
            else:
                score += 0.0
        else:
            if partial.is_sorted_stack(sd):
                score += self.sorted_bonus

            # Si el contenedor encaja exactamente, suele ser una buena señal.
            if dest_top == src_top:
                score += self.same_group_bonus

        # Ligera preferencia por no tocar pilas muy altas si hay empate.
        score += 0.01 * dest_h
        return score

    def allowed(self, partial, memory, candidates):
        allowed = []
        for a in candidates:
            so = a.so
            sd = a.sd

            if so == sd:
                continue
            if partial.h(so) <= 0:
                continue
            if partial.h(sd) >= partial.H:
                continue

            # Permitimos tanto vacías como no vacías: el orden lo decide el score.
            allowed.append(a)

        allowed.sort(key=lambda a: (self._score(partial, a), a.sd, a.so))
        return allowed


def build_component(problem, **params):
    return RuleMachine(
        problem,
        [
            SafeSortedDestinationRule(
                prefer_empty=params.get("prefer_empty", True),
                empty_bonus=params.get("empty_bonus", -1.5),
